const GetStatsCategories = `-- name: GetStatsCategories :many
SELECT category AS name, COUNT(*)::bigint AS count
FROM parts
WHERE to_delete_at IS NULL AND quantity >= 1 AND deleted_at IS NULL AND category != ''
GROUP BY category
ORDER BY count DESC
`

type GetStatsCategoriesRow struct {
	Name  string `json:"name"`
	Count int64  `json:"count"`
}

func (q *Queries) GetStatsCategories(ctx context.Context) ([]GetStatsCategoriesRow, error) {
	rows, err := q.db.Query(ctx, GetStatsCategories)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []GetStatsCategoriesRow{}
	for rows.Next() {
		var i GetStatsCategoriesRow
		if err := rows.Scan(&i.Name, &i.Count); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const GetStatsTotals = `-- name: GetStatsTotals :one
SELECT
    COUNT(*)::bigint AS total_parts,
    COALESCE(SUM(quantity), 0)::bigint AS total_quantity,
    COALESCE(SUM(price * quantity), 0)::float8 AS total_value
FROM parts
WHERE to_delete_at IS NULL AND quantity >= 1 AND deleted_at IS NULL
`

type GetStatsTotalsRow struct {
	TotalParts    int64   `json:"total_parts"`
	TotalQuantity int64   `json:"total_quantity"`
	TotalValue    float64 `json:"total_value"`
}

func (q *Queries) GetStatsTotals(ctx context.Context) (GetStatsTotalsRow, error) {
	row := q.db.QueryRow(ctx, GetStatsTotals)
	var i GetStatsTotalsRow
	err := row.Scan(&i.TotalParts, &i.TotalQuantity, &i.TotalValue)
	return i, err
}

const GetStatsTotalsBefore = `-- name: GetStatsTotalsBefore :one
SELECT
    COUNT(*)::bigint AS prev_parts,
    COALESCE(SUM(quantity), 0)::bigint AS prev_quantity,
    COALESCE(SUM(price * quantity), 0)::float8 AS prev_value
FROM parts
WHERE to_delete_at IS NULL
  AND quantity >= 1
  AND created_at < $1
  AND (deleted_at IS NULL OR deleted_at >= $1)
`

type GetStatsTotalsBeforeRow struct {
	PrevParts    int64   `json:"prev_parts"`
	PrevQuantity int64   `json:"prev_quantity"`
	PrevValue    float64 `json:"prev_value"`
}

func (q *Queries) GetStatsTotalsBefore(ctx context.Context, createdAt pgtype.Timestamptz) (GetStatsTotalsBeforeRow, error) {
	row := q.db.QueryRow(ctx, GetStatsTotalsBefore, createdAt)
	var i GetStatsTotalsBeforeRow
	err := row.Scan(&i.PrevParts, &i.PrevQuantity, &i.PrevValue)
	return i, err
}

const GetSupplierBatches = `-- name: GetSupplierBatches :many
SELECT
    sub.batch_code,
    COALESCE(MAX(NULLIF(BTRIM(sub.brand), '')), '')::text AS brand_name,
    COALESCE(MAX(NULLIF(BTRIM(sub.model), '')), '')::text AS model_name,
    COALESCE(MAX(NULLIF(BTRIM(sub.car_release_date), '')), '')::text AS release_date,
    COALESCE(MAX(NULLIF(BTRIM(sub.vin), '')), '')::text AS car_vin,
    COUNT(*)::bigint AS zero_count
FROM (
    SELECT
        CASE
            WHEN supplier_code IS NOT NULL AND BTRIM(supplier_code) != '' THEN BTRIM(supplier_code)
            ELSE 'car:' || COALESCE(BTRIM(brand), '') || '|' || COALESCE(BTRIM(model), '') || '|' || COALESCE(BTRIM(car_release_date), '') || '|' || COALESCE(BTRIM(vin), '')
        END AS batch_code,
        brand,
        model,
        car_release_date,
        vin,
        created_at
    FROM parts
    WHERE quantity = 0 AND to_delete_at IS NULL AND deleted_at IS NULL
) sub
GROUP BY sub.batch_code
ORDER BY MAX(sub.created_at) DESC NULLS LAST, sub.batch_code DESC
`

type GetSupplierBatchesRow struct {
	BatchCode   interface{} `json:"batch_code"`
	BrandName   string      `json:"brand_name"`
	ModelName   string      `json:"model_name"`
	ReleaseDate string      `json:"release_date"`
	CarVin      string      `json:"car_vin"`
	ZeroCount   int64       `json:"zero_count"`
}

func (q *Queries) GetSupplierBatches(ctx context.Context) ([]GetSupplierBatchesRow, error) {
	rows, err := q.db.Query(ctx, GetSupplierBatches)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []GetSupplierBatchesRow{}
	for rows.Next() {
		var i GetSupplierBatchesRow
		if err := rows.Scan(
			&i.BatchCode,
			&i.BrandName,
			&i.ModelName,
			&i.ReleaseDate,
			&i.CarVin,
			&i.ZeroCount,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

